// src/components/Register.jsx
import React, { useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import Webcam from "react-webcam";
import { getAuth, createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import "./CSS/Register.css";

const Register = () => {
  const webcamRef = useRef(null);
  const navigate = useNavigate();

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  // Keep the same 300x300 framing you use on FaceRecognition
  const videoConstraints = { width: 300, height: 300, facingMode: "user" };

  const capture = () => webcamRef.current?.getScreenshot() || null;

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const image = capture();
      if (!name.trim() || !email.trim() || !password.trim() || !image) {
        alert("Please fill all fields and ensure your face is captured.");
        setLoading(false);
        return;
      }

      const auth = getAuth();
      const emailNorm = email.trim().toLowerCase();

      const cred = await createUserWithEmailAndPassword(auth, emailNorm, password);
      await updateProfile(cred.user, { displayName: name.trim() });

      // Save face to backend
      const res = await fetch("http://127.0.0.1:5000/register-face", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: emailNorm, image }),
      });

      const json = await res.json();
      if (!json.success) {
        throw new Error(json.error || "Face registration failed.");
      }

      alert("Registered successfully!");
      navigate("/login");
    } catch (err) {
      console.error("[Register] Error:", err);
      alert(`Registration failed: ${err.message || "Unexpected error"}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="register-container">
      {/* Keep your existing layout and styles */}
      <h2>Register</h2>
      <form onSubmit={handleRegister}>
        <input
          type="text"
          placeholder="Full Name"
          value={name}
          required
          onChange={(e) => setName(e.target.value)}
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          required
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          required
          onChange={(e) => setPassword(e.target.value)}
        />

        {/* 300x300 webcam area to match FaceRecognition */}
        <div className="face-container">
          <Webcam
            ref={webcamRef}
            audio={false}
            width={300}
            height={300}
            screenshotFormat="image/png"         // PNG to match backend
            videoConstraints={videoConstraints}
            className="webcam"
          />
        </div>

        <button type="submit" disabled={loading}>
          {loading ? "Registering..." : "Register"}
        </button>
      </form>
    </div>
  );
};

export default Register;
